    (if list_eq_dec Z.eq_dec fl []
     then [FCT (caddr KFmh) 8 g; FCT (g + 8) 8 g; FCT g 8 g]
     else [FCT hd0 8 g; FCT (t + 8) 8 g; FCT g 8 t; FCT (g + 8) 8 hd0]) ++ zws.

